export default grammar({
  name: "keyword_immediate_singleton",
  word: $ => $.word,
  rules: {
    program: $ => choice(
      $.literal,
      $.fixed_regex,
      $.singleton_class,
      $.grouped,
      $.exact_repeat,
      $.general_regex,
      $.optional_regex,
      $.alternative_regex,
      $.fixed_length_regex,
      $.required_literal,
      $.required_regex,
    ),
    literal: $ => seq("literal:", choice($.word, $.literal_statement)),
    literal_statement: $ => seq(token.immediate(prec(2, "match")), $.word),
    fixed_regex: $ => seq("regex:", choice($.word, $.regex_statement)),
    regex_statement: $ => seq(token.immediate(prec(2, /match/)), $.word),
    singleton_class: $ => seq("class:", choice($.word, $.class_statement)),
    class_statement: $ => seq(token.immediate(prec(2, /m[a]tch/)), $.word),
    grouped: $ => seq("grouped:", choice($.word, $.grouped_statement)),
    grouped_statement: $ => seq(token.immediate(prec(2, /(?:match|match)/)), $.word),
    exact_repeat: $ => seq("repeat:", choice($.word, $.repeat_statement)),
    repeat_statement: $ => seq(token.immediate(prec(2, /mat{1}ch/)), $.word),
    general_regex: $ => seq("general:", choice($.word, $.general_statement)),
    general_statement: $ => seq($.prefix_keyword, $.word),
    prefix_keyword: _ => token.immediate(prec(2, /match+/)),
    optional_regex: $ => seq("optional:", choice($.word, $.optional_statement)),
    optional_statement: $ => seq($.optional_keyword, $.word),
    optional_keyword: _ => token.immediate(prec(2, /match(?:x)?/)),
    alternative_regex: $ => seq("alternative:", choice($.word, $.alternative_statement)),
    alternative_statement: $ => seq($.alternative_keyword, $.word),
    alternative_keyword: _ => token.immediate(prec(2, /match|matchx/)),
    fixed_length_regex: $ => seq("length:", choice($.word, $.length_statement)),
    length_statement: $ => seq($.length_keyword, $.word),
    length_keyword: _ => token.immediate(prec(2, /[a-z]{5}/)),
    required_literal: $ => seq("literal-only:", $.literal_statement),
    required_regex: $ => seq("regex-only:", $.regex_statement),
    word: _ => /[a-z]+/,
  },
});